use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::fs;
fn main(){let r="/home/ubuntu/src/zopro-perf-work/signed-complex-square176";let mut plan:Value=serde_json::from_slice(&fs::read(format!("{r}/model-plan.json")).unwrap()).unwrap();let mut pins:Value=serde_json::from_slice(&fs::read(format!("{r}/model-pins.json")).unwrap()).unwrap();let name=format!("{r}/model-fixed.rs");for p in[&name,&format!("{r}/repair.rs")]{pins[p]=json!(format!("{:x}",Sha256::digest(fs::read(p).unwrap())));}plan["source_pins"]=json!(format!("{r}/model-fixed-pins.json"));let old=format!("{r}/model.rs");for v in plan["steps"][0]["argv"].as_array_mut().unwrap(){if *v==old{*v=json!(&name);}}
fs::write(format!("{r}/model-fixed-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(format!("{r}/model-fixed-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Only model integer/shift annotations repaired; no model execution occurred before this compile repair");}
